def help_for(endpoint, section, outbound=None):
    if endpoint == 'tunnel_form' and outbound:
        protocol = outbound.get('protocol')
        if protocol in SERVICE_HELP and outbound.get('native', {}).get('type') != protocol.lower():
            return SERVICE_HELP[protocol]
        if outbound.get('native', {}).get('type') == 'openvpn-client':
            return EDITOR_HELP['openvpn_new']
    return EDITOR_HELP.get(endpoint) or SECTION_HELP.get(section)
